package synk

import (
	"path"
	"strings"
	"time"
)

// isReplacementSiblingName recognizes names generated by
// replacementSiblingName. Recognition alone never proves artifact ownership.
func isReplacementSiblingName(name string) bool {
	return replacementSiblingKind(name) != ""
}

// replacementSiblingKind is shared by reconciliation and verification.
// Empty means the name does not match the generated replacement namespace.
func replacementSiblingKind(name string) string {
	base := path.Base(name)
	marker := strings.LastIndex(base, ".icloud-synk-")
	if marker < 0 {
		return ""
	}

	remainder := base[marker+len(".icloud-synk-"):]
	kind, stamp, ok := strings.Cut(remainder, "-")
	if !ok || (kind != "new" && kind != "backup" && kind != "failed") {
		return ""
	}

	if len(stamp) < 25 {
		return ""
	}

	timestamp := stamp[:25]
	parsed, err := time.Parse("20060102T150405.000000000", timestamp)
	if err != nil || parsed.Format("20060102T150405.000000000") != timestamp {
		return ""
	}

	suffix := stamp[25:]
	if suffix == "" || (strings.HasPrefix(suffix, ".") && len(suffix) > 1) {
		return kind
	}
	return ""
}
